import json
import boto3
from botocore.exceptions import ClientError

# A step with no cloud integration bound reaches signing time and raises
# NoCredentialsError as a bare traceback. The agent would then file that
# traceback as an observation. Fail here instead, with a sentence that names
# what is missing and who fixes it.
_creds = boto3.session.Session().get_credentials()
if _creds is None:
    print(json.dumps({"error": "No AWS credentials reached this step. Bind an AWS cloud "
                               "integration to this automation under Cloud Integrations, "
                               "and make sure it is available to this project."}))
    raise SystemExit(1)

REGION = "{{Region}}"
ec2 = boto3.session.Session(region_name=REGION).client("ec2")

OPEN = ("0.0.0.0/0", "::/0")


def described(perm):
    """A port range as a human reads it, not as the API models it."""
    if perm.get("IpProtocol") == "-1":
        return "ALL traffic"
    lo, hi = perm.get("FromPort"), perm.get("ToPort")
    proto = perm.get("IpProtocol", "?")
    if lo is None:
        return proto
    return proto + " " + (str(lo) if lo == hi else str(lo) + "-" + str(hi))


out = {"region": REGION, "groups": [], "errors": []}
try:
    groups = [g for page in ec2.get_paginator("describe_security_groups").paginate()
              for g in page["SecurityGroups"]]
except ClientError as e:
    print(json.dumps({"error": "could not describe security groups: " + str(e)}))
    raise SystemExit(1)

# Which groups are actually attached to something. A wide-open rule on a group
# nobody uses is a different severity from one in front of a live instance, and
# the agent cannot tell them apart without this.
attached = set()
try:
    for page in ec2.get_paginator("describe_network_interfaces").paginate():
        for eni in page["NetworkInterfaces"]:
            for g in eni.get("Groups", []):
                attached.add(g["GroupId"])
except ClientError as e:
    out["errors"].append({"step": "describe_network_interfaces",
                          "error": e.response["Error"]["Code"]})
    attached = None

for g in groups:
    exposures = []
    for perm in g.get("IpPermissions", []):
        cidrs = [r.get("CidrIp") for r in perm.get("IpRanges", [])]
        cidrs += [r.get("CidrIpv6") for r in perm.get("Ipv6Ranges", [])]
        for cidr in cidrs:
            if cidr in OPEN:
                exposures.append({"port": described(perm), "cidr": cidr})
    if exposures:
        out["groups"].append({
            "groupId": g["GroupId"],
            "groupName": g.get("GroupName"),
            "vpcId": g.get("VpcId"),
            "description": g.get("Description"),
            "inUse": None if attached is None else (g["GroupId"] in attached),
            "openTo": exposures,
        })

out["summary"] = {
    "groupsScanned": len(groups),
    "groupsOpenToInternet": len(out["groups"]),
    "attachmentKnown": attached is not None,
}
print(json.dumps(out, indent=2))
